pts=[(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)]
lines=set()
for i,(r,c) in enumerate(pts):
 for R,C in pts[i+1:]:
  dr=R-r; dc=C-c
  if dr==0: step=(0,1 if dc>0 else -1)
  elif dc==0: step=(1 if dr>0 else -1,0)
  elif abs(dr)==abs(dc): step=(1 if dr>0 else -1,1 if dc>0 else -1)
  else: continue
  rr,cc=r+step[0],c+step[1]
  while (rr,cc)!=(R,C):
   lines.add((rr,cc));rr+=step[0];cc+=step[1]
