pts=[(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)]
segs=set()
for i,(r,c) in enumerate(pts):
 for R,C in pts[i+1:]:
  dr,dc=R-r,C-c
  if dr==0 and dc!=0: sr,sc=0,(1 if dc>0 else -1)
  elif dc==0 and dr!=0: sr,sc=(1 if dr>0 else -1),0
  elif abs(dr)==abs(dc) and dr!=0: sr,sc=(1 if dr>0 else -1),(1 if dc>0 else -1)
  else: continue
  rr,cc=r+sr,c+sc
  while (rr,cc)!=(R,C):
   segs.add((rr,cc));rr+=sr;cc+=sc
G=[[8]*8 for _ in range(30)]
for r,c in pts:G[r][c]=7
for r,c in segs:
 if G[r][c]==8:G[r][c]=3
print('segments',sorted(segs))
print('\n'.join('['+','.join(map(str,row))+'],' for row in G))
